-- Target PostgreSQL design. This file is not the active local SQLite adapter.
-- Apply in a new application schema after selecting an authentication provider.
BEGIN;
CREATE TYPE source_status AS ENUM ('VERIFIED_PYQ','SOURCE_VERIFIED','QUESTION_TEXT_VERIFIED','ANSWER_KEY_VERIFIED','SOURCE_PARTIALLY_VERIFIED','MEMORY_BASED_QUESTION','GENERATED_PRACTICE_QUESTION','EXPECTED_QUESTION','QUESTION_MODEL_DERIVED_FROM_PYQS');
CREATE TYPE learning_state AS ENUM ('UNSEEN','EXPOSED','RECOGNISING','UNDERSTANDING','PRACTISING','UNSTABLE','CONFUSED','REPAIRING','RECALL_READY','MASTERED_SHORT_TERM','MASTERED_STABLE','REVISION_DUE','REGRESSED');
CREATE TABLE users(id uuid PRIMARY KEY, auth_subject text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), display_name text, is_demo boolean NOT NULL DEFAULT false, timezone text NOT NULL DEFAULT 'Asia/Kolkata', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exams(id text PRIMARY KEY, title text NOT NULL, exam_target text NOT NULL CHECK(exam_target IN ('SI','Constable')), authority text NOT NULL);
CREATE TABLE exam_targets(profile_id uuid REFERENCES profiles(id), exam_id text REFERENCES exams(id), PRIMARY KEY(profile_id,exam_id));
CREATE TABLE subjects(id text PRIMARY KEY, title text NOT NULL);
CREATE TABLE topics(id text PRIMARY KEY, subject_id text NOT NULL REFERENCES subjects(id), title text NOT NULL, chronology_start integer, chronology_end integer, sort_order integer NOT NULL);
CREATE TABLE subtopics(id text PRIMARY KEY, topic_id text NOT NULL REFERENCES topics(id), title text NOT NULL, reviewed_at timestamptz);
CREATE TABLE microconcepts(id text PRIMARY KEY, subtopic_id text NOT NULL REFERENCES subtopics(id), title text NOT NULL, review_status text NOT NULL DEFAULT 'pending');
CREATE TABLE prerequisites(concept_id text REFERENCES microconcepts(id), prerequisite_id text REFERENCES microconcepts(id), rationale text NOT NULL, PRIMARY KEY(concept_id,prerequisite_id), CHECK(concept_id<>prerequisite_id));
CREATE TABLE question_models(id text PRIMARY KEY, title text NOT NULL, recognition_clue text NOT NULL);
CREATE TABLE papers(id uuid PRIMARY KEY, exam_id text NOT NULL REFERENCES exams(id), year integer NOT NULL, stage text NOT NULL, language text NOT NULL, source_url text, document_sha256 text, official_key_url text, official_key_sha256 text, key_status text NOT NULL DEFAULT 'unverified', reviewed_at timestamptz);
CREATE TABLE questions(id text PRIMARY KEY, concept_id text NOT NULL REFERENCES microconcepts(id), model_id text NOT NULL REFERENCES question_models(id), source_class source_status NOT NULL, stem text NOT NULL, language text NOT NULL DEFAULT 'en', difficulty smallint NOT NULL CHECK(difficulty BETWEEN 1 AND 5), exam_relevance numeric NOT NULL CHECK(exam_relevance BETWEEN 0 AND 1), content_version integer NOT NULL DEFAULT 1, published boolean NOT NULL DEFAULT false, reviewed_by text, reviewed_at timestamptz);
CREATE TABLE question_options(id uuid PRIMARY KEY, question_id text NOT NULL REFERENCES questions(id), position smallint NOT NULL CHECK(position BETWEEN 0 AND 5), text text NOT NULL, correct boolean NOT NULL DEFAULT false, attraction text NOT NULL, rationale text NOT NULL, misconception_concept_id text REFERENCES microconcepts(id), UNIQUE(question_id,position));
CREATE UNIQUE INDEX one_correct_option ON question_options(question_id) WHERE correct;
-- Publication validator must additionally require >=2 options and exactly 1 correct option.
CREATE TABLE question_sources(id uuid PRIMARY KEY, question_id text NOT NULL REFERENCES questions(id), paper_id uuid REFERENCES papers(id), document_title text NOT NULL, document_url text, local_document_sha256 text, pdf_page integer, printed_page text, question_number text, paragraph_locator text, source_verified boolean NOT NULL DEFAULT false, text_verified boolean NOT NULL DEFAULT false, key_verified boolean NOT NULL DEFAULT false, reviewed_at timestamptz, reviewer text);
CREATE TABLE question_explanations(question_id text PRIMARY KEY REFERENCES questions(id), rationale text NOT NULL, identify_model text NOT NULL, examiner_intention text NOT NULL, clue text NOT NULL, trap text NOT NULL, elimination text NOT NULL, timeline_position text, memory_anchor text NOT NULL, version integer NOT NULL);
CREATE TABLE question_relations(question_id text REFERENCES questions(id), related_id text REFERENCES questions(id), relationship text NOT NULL CHECK(relationship IN ('rewording','opposite_trap','related_pyq','similar_wording','prerequisite')), PRIMARY KEY(question_id,related_id,relationship));
CREATE TABLE hints(id uuid PRIMARY KEY, question_id text NOT NULL REFERENCES questions(id), level smallint NOT NULL, content text NOT NULL, UNIQUE(question_id,level));
CREATE TABLE learning_sessions(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), mode text NOT NULL, rules_version text NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, status text NOT NULL, planned_count integer NOT NULL);
CREATE TABLE session_questions(session_id uuid REFERENCES learning_sessions(id), question_id text REFERENCES questions(id), queue_index integer NOT NULL, selection_reason text NOT NULL, PRIMARY KEY(session_id,queue_index));
CREATE TABLE question_exposures(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), session_id uuid NOT NULL REFERENCES learning_sessions(id), question_id text NOT NULL REFERENCES questions(id), viewed_at timestamptz NOT NULL, abandoned_at timestamptz);
CREATE TABLE attempts(id uuid PRIMARY KEY, request_id uuid UNIQUE NOT NULL, profile_id uuid NOT NULL REFERENCES profiles(id), session_id uuid NOT NULL REFERENCES learning_sessions(id), question_id text NOT NULL REFERENCES questions(id), content_version integer NOT NULL, selected_option_id uuid NOT NULL REFERENCES question_options(id), correct boolean NOT NULL, response_ms integer NOT NULL CHECK(response_ms>=0), first_selection_ms integer CHECK(first_selection_ms>=0), answer_changes integer NOT NULL DEFAULT 0, hint_used boolean NOT NULL, submitted_at timestamptz NOT NULL, is_demo boolean NOT NULL DEFAULT false);
CREATE INDEX attempts_profile_question_time ON attempts(profile_id,question_id,submitted_at DESC);
CREATE TABLE confidence_responses(attempt_id uuid PRIMARY KEY REFERENCES attempts(id), probability numeric NOT NULL CHECK(probability BETWEEN 0 AND 1));
CREATE TABLE attempt_events(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), attempt_id uuid REFERENCES attempts(id), session_id uuid REFERENCES learning_sessions(id), question_id text REFERENCES questions(id), event_type text NOT NULL, occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX attempt_events_profile_time ON attempt_events(profile_id,occurred_at DESC);
CREATE TABLE session_events(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES learning_sessions(id), event_type text NOT NULL, occurred_at timestamptz NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE topic_mastery(profile_id uuid REFERENCES profiles(id), concept_id text REFERENCES microconcepts(id), state learning_state NOT NULL DEFAULT 'UNSEEN', sample_size integer NOT NULL DEFAULT 0, first_attempt_accuracy numeric, recent_accuracy numeric, independent_accuracy numeric, retention_accuracy numeric, speed_median_ms integer, confidence_gap numeric, model_coverage numeric, spacing_stability numeric, model_version text NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY(profile_id,concept_id));
CREATE TABLE model_mastery(profile_id uuid REFERENCES profiles(id), model_id text REFERENCES question_models(id), sample_size integer NOT NULL, accuracy numeric, median_response_ms integer, hint_independence numeric, model_version text NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY(profile_id,model_id));
CREATE TABLE confusion_pairs(id text PRIMARY KEY, concept_a text NOT NULL REFERENCES microconcepts(id), concept_b text NOT NULL REFERENCES microconcepts(id), comparison_note text NOT NULL, source_id uuid REFERENCES question_sources(id), CHECK(concept_a<>concept_b), UNIQUE(concept_a,concept_b));
CREATE TABLE confusion_events(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), pair_id text NOT NULL REFERENCES confusion_pairs(id), attempt_id uuid NOT NULL REFERENCES attempts(id), wrong_direction text NOT NULL, model_id text NOT NULL REFERENCES question_models(id), observed_at timestamptz NOT NULL);
CREATE TABLE confusion_mastery(profile_id uuid REFERENCES profiles(id), pair_id text REFERENCES confusion_pairs(id), confusion_count integer NOT NULL DEFAULT 0, last_occurrence timestamptz, comparison_accuracy numeric, revision_count integer NOT NULL DEFAULT 0, resolved boolean NOT NULL DEFAULT false, resolution_evidence jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(profile_id,pair_id));
CREATE TABLE mistake_events(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), attempt_id uuid NOT NULL REFERENCES attempts(id), classification text NOT NULL, evidence jsonb NOT NULL, inference_strength numeric CHECK(inference_strength BETWEEN 0 AND 1), created_at timestamptz NOT NULL);
CREATE TABLE revision_items(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), concept_id text NOT NULL REFERENCES microconcepts(id), next_question_id text REFERENCES questions(id), due_at timestamptz NOT NULL, interval_days numeric NOT NULL, priority numeric NOT NULL, reason text NOT NULL, rules_version text NOT NULL, UNIQUE(profile_id,concept_id));
CREATE INDEX revision_profile_due ON revision_items(profile_id,due_at);
CREATE TABLE revision_events(id uuid PRIMARY KEY, revision_id uuid NOT NULL REFERENCES revision_items(id), attempt_id uuid REFERENCES attempts(id), event_type text NOT NULL, old_due_at timestamptz, new_due_at timestamptz, occurred_at timestamptz NOT NULL);
CREATE TABLE recommendations(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), action_type text NOT NULL, concept_id text REFERENCES microconcepts(id), evidence jsonb NOT NULL, rationale text NOT NULL, rules_version text NOT NULL, created_at timestamptz NOT NULL, expires_at timestamptz, overridden_at timestamptz, completed_at timestamptz);
CREATE TABLE mentor_interventions(id uuid PRIMARY KEY, recommendation_id uuid NOT NULL REFERENCES recommendations(id), profile_id uuid NOT NULL REFERENCES profiles(id), content text NOT NULL, source_ids uuid[] NOT NULL DEFAULT '{}', generator_version text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE current_affairs_links(id uuid PRIMARY KEY, concept_id text NOT NULL REFERENCES microconcepts(id), title text NOT NULL, source_url text NOT NULL, published_at timestamptz NOT NULL, historical_connection text NOT NULL, si_constable_relevance text NOT NULL, reviewed_at timestamptz);
CREATE TABLE expected_questions(question_id text PRIMARY KEY REFERENCES questions(id), priority text NOT NULL CHECK(priority IN ('High Priority','Moderate Priority','Watchlist','Revision Worthy')), evidence_rationale text NOT NULL, evidence_source_ids uuid[] NOT NULL DEFAULT '{}');
CREATE TABLE bookmarks(profile_id uuid REFERENCES profiles(id), question_id text REFERENCES questions(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(profile_id,question_id));
CREATE TABLE notes(id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), concept_id text REFERENCES microconcepts(id), question_id text REFERENCES questions(id), content text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());

-- Ownership policy pattern. The authenticated trusted server sets app.user_id
-- transaction-locally; the browser never chooses it. Additional role grants and
-- FORCE ROW LEVEL SECURITY must be reviewed for the selected deployment roles.
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON profiles USING (user_id = nullif(current_setting('app.user_id',true),'')::uuid) WITH CHECK (user_id = nullif(current_setting('app.user_id',true),'')::uuid);
DO $$ DECLARE table_name text; BEGIN
 FOREACH table_name IN ARRAY ARRAY['exam_targets','learning_sessions','question_exposures','attempts','attempt_events','topic_mastery','model_mastery','confusion_events','confusion_mastery','mistake_events','revision_items','recommendations','mentor_interventions','bookmarks','notes'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);
  EXECUTE format('CREATE POLICY own_learning ON %I USING (profile_id IN (SELECT id FROM profiles)) WITH CHECK (profile_id IN (SELECT id FROM profiles))',table_name);
 END LOOP;
END $$;
-- Session, confidence and revision child tables must be accessed through
-- authenticated parent-scoped repositories; do not grant a public database role.
COMMIT;
